mapper.select:
SELECT product_id, creator_id, product_type, title, short_title,
       price, detail, status, created_at, updated_at, deleted_at
FROM product_1
WHERE creator_id = #{creatorId}
  AND product_id = #{productId}
  AND deleted_at IS NULL

mapper.update:
UPDATE product_1
SET title        = #{title},
    short_title  = #{shortTitle},
    price        = #{price},
    detail       = #{detail},
    updated_at   = #{updatedAt}
WHERE product_id = #{productId}
  AND creator_id = #{creatorId}
  AND deleted_at IS NULL

UPDATE product_1
SET status     = #{status},
    updated_at = #{updatedAt}
WHERE product_id = #{productId}
  AND creator_id = #{creatorId}
  AND deleted_at IS NULL

UPDATE product_1
SET deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE product_id = #{productId}
  AND creator_id = #{creatorId}
  AND deleted_at IS NULL
